/**
 * Validates and normalises a raw interval list into an array of fresh
 * `[start, end]` pairs, throwing on any malformed input.
 * @param {unknown} intervals Interval list.
 * @returns {Array<[number, number]>} Validated, freshly-allocated intervals (unsorted, may include empties).
 */
function validate(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError('interval list must be an array');
  }
  const out = [];
  for (const item of intervals) {
    if (!Array.isArray(item) || item.length !== 2) {
      throw new TypeError('interval must be a two-element array');
    }
    const [start, end] = item;
    if (
      typeof start !== 'number' ||
      typeof end !== 'number' ||
      !Number.isSafeInteger(start) ||
      !Number.isSafeInteger(end)
    ) {
      throw new TypeError('interval bounds must be safe integers');
    }
    if (start > end) {
      throw new RangeError('interval start must not exceed end');
    }
    out.push([start, end]);
  }
  return out;
}

/**
 * Sorts, drops empty intervals, and coalesces overlapping or touching ones.
 * @param {Array<[number, number]>} validated Already-validated interval list.
 * @returns {Array<[number, number]>} Normalised list.
 */
function normalizeValidated(validated) {
  const nonEmpty = validated.filter(([start, end]) => start < end);
  nonEmpty.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const out = [];
  for (const [start, end] of nonEmpty) {
    if (out.length > 0 && start <= out[out.length - 1][1]) {
      if (end > out[out.length - 1][1]) out[out.length - 1][1] = end;
    } else {
      out.push([start, end]);
    }
  }
  return out;
}

/**
 * Normalises a list of intervals: drops empties, sorts, and coalesces
 * overlapping or touching intervals.
 * @param {unknown} intervals Interval list.
 * @returns {Array<[number, number]>} Normalised list.
 */
export function normalize(intervals) {
  return normalizeValidated(validate(intervals));
}

/**
 * Union of two interval lists.
 * @param {unknown} a First interval list.
 * @param {unknown} b Second interval list.
 * @returns {Array<[number, number]>} Normalised union.
 */
export function merge(a, b) {
  const va = validate(a);
  const vb = validate(b);
  return normalizeValidated([...va, ...vb]);
}

/**
 * Intersection of two interval lists. Touching intervals do not intersect.
 * @param {unknown} a First interval list.
 * @param {unknown} b Second interval list.
 * @returns {Array<[number, number]>} Normalised intersection.
 */
export function intersect(a, b) {
  const na = normalizeValidated(validate(a));
  const nb = normalizeValidated(validate(b));
  const out = [];
  let i = 0;
  let j = 0;
  while (i < na.length && j < nb.length) {
    const start = Math.max(na[i][0], nb[j][0]);
    const end = Math.min(na[i][1], nb[j][1]);
    if (start < end) out.push([start, end]);
    if (na[i][1] < nb[j][1]) i += 1;
    else j += 1;
  }
  return out;
}

/**
 * Relative complement `a \ b`.
 * @param {unknown} a Interval list to subtract from.
 * @param {unknown} b Interval list to remove.
 * @returns {Array<[number, number]>} Normalised difference.
 */
export function subtract(a, b) {
  const na = normalizeValidated(validate(a));
  const nb = normalizeValidated(validate(b));
  const out = [];
  let j = 0;
  for (const [start, end] of na) {
    let cur = start;
    while (j < nb.length && nb[j][1] <= cur) j += 1;
    let k = j;
    while (k < nb.length && nb[k][0] < end) {
      if (nb[k][0] > cur) out.push([cur, nb[k][0]]);
      cur = Math.max(cur, nb[k][1]);
      k += 1;
    }
    if (cur < end) out.push([cur, end]);
  }
  return out;
}

/**
 * Total length covered by a list of intervals, counting overlaps once.
 * @param {unknown} intervals Interval list.
 * @returns {number} Number of integers covered.
 */
export function coverage(intervals) {
  const normalized = normalizeValidated(validate(intervals));
  let total = 0;
  for (const [start, end] of normalized) total += end - start;
  return total;
}
